use clap::Parser;
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use crossterm::execute;
use crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::backend::{Backend, CrosstermBackend};
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Paragraph};
use ratatui::Frame;
use regex::Regex;
use std::error::Error;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

mod flamegraph;
mod ui;

use flamegraph::{FlameGraph, Frame as FlameFrame};
use ui::App;

#[derive(Parser, Debug)]
#[command(name = "flamelens")]
#[command(about = "Interactive flamegraph viewer for the terminal", version = "0.3.1")]
struct Args {
    /// Profile data filename
    filename: Option<PathBuf>,

    /// Whether to sort the stacks by time spent
    #[arg(long)]
    sorted: bool,

    /// Print data to stdout on exit. Useful when piping to other tools
    #[arg(long)]
    echo: bool,

    /// Show debug info
    #[arg(long)]
    debug: bool,
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = Args::parse();

    // Read input data
    let data = if let Some(filename) = &args.filename {
        fs::read_to_string(filename)?
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    };

    // If echo flag is set, print the data to stdout
    if args.echo {
        print!("{}", data);
    }

    // Parse the flamegraph data
    let flamegraph = FlameGraph::from_folded_stacks(&data, args.sorted)?;

    // Run the TUI
    let mut app = App::new(flamegraph);
    if let Some(filename) = &args.filename {
        app.filename = filename.to_string_lossy().to_string();
    }

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    // Run the app
    let res = run_app(&mut terminal, &mut app);

    // Restore terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("Error: {}", err);
    }

    Ok(())
}

fn run_app<B: Backend>(
    terminal: &mut ratatui::Terminal<B>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui::draw(f, app))?;

        if event::poll(std::time::Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => {
                        if !app.in_search_mode {
                            break;
                        } else {
                            app.cancel_search();
                        }
                    }
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        break;
                    }
                    KeyCode::Char('/') if !app.in_search_mode => {
                        app.start_search();
                    }
                    KeyCode::Char('#') if !app.in_search_mode => {
                        app.search_like_selected();
                    }
                    KeyCode::Char('n') if !app.in_search_mode && app.has_match => {
                        app.next_match();
                    }
                    KeyCode::Char('N') if !app.in_search_mode && app.has_match => {
                        app.prev_match();
                    }
                    KeyCode::Char('r') if !app.in_search_mode => {
                        app.reset_view();
                    }
                    KeyCode::Enter if app.in_search_mode => {
                        app.execute_search();
                    }
                    KeyCode::Char(c) if app.in_search_mode => {
                        app.search_pattern.push(c);
                    }
                    KeyCode::Backspace if app.in_search_mode => {
                        app.search_pattern.pop();
                    }
                    KeyCode::Enter if !app.in_search_mode => {
                        app.zoom_in();
                    }
                    KeyCode::Esc if !app.in_search_mode => {
                        app.zoom_out();
                    }
                    KeyCode::Char('h') | KeyCode::Left if !app.in_search_mode => {
                        app.move_cursor_left();
                    }
                    KeyCode::Char('l') | KeyCode::Right if !app.in_search_mode => {
                        app.move_cursor_right();
                    }
                    KeyCode::Char('j') | KeyCode::Down if !app.in_search_mode => {
                        app.move_cursor_down();
                    }
                    KeyCode::Char('k') | KeyCode::Up if !app.in_search_mode => {
                        app.move_cursor_up();
                    }
                    KeyCode::Char('f') if !app.in_search_mode => {
                        app.scroll_down();
                    }
                    KeyCode::Char('b') if !app.in_search_mode => {
                        app.scroll_up();
                    }
                    KeyCode::Char('G') if !app.in_search_mode => {
                        app.scroll_to_bottom();
                    }
                    KeyCode::Char('g') if !app.in_search_mode => {
                        app.scroll_to_top();
                    }
                    _ => {}
                }
            }
        }
    }

    Ok(())
}
