use std::collections::HashMap;
use std::error::Error;

#[derive(Debug, Clone)]
pub struct Frame {
    pub name: String,
    pub samples: u64,
    pub children: Vec<usize>, // indices to other frames
}

#[derive(Debug)]
pub struct FlameGraph {
    pub frames: Vec<Frame>,
    pub root_indices: Vec<usize>,
    pub total_samples: u64,
}

impl FlameGraph {
    pub fn from_folded_stacks(data: &str, _sorted: bool) -> Result<Self, Box<dyn Error>> {
        let mut frames: Vec<Frame> = Vec::new();
        let mut root_indices: Vec<usize> = Vec::new();
        let mut frame_map: HashMap<String, usize> = HashMap::new();
        let mut total_samples = 0;

        for line in data.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }

            // Parse the line: stack;trace;path samples
            let parts: Vec<&str> = line.rsplitn(2, ' ').collect();
            if parts.len() != 2 {
                continue;
            }

            let samples: u64 = parts[0].trim().parse().unwrap_or(0);
            let stack = parts[1];
            total_samples += samples;

            let stack_parts: Vec<&str> = stack.split(';').collect();

            // Find or create root frame
            let root_name = stack_parts[0].to_string();
            let root_idx = if let Some(&idx) = frame_map.get(&root_name) {
                frames[idx].samples += samples;
                idx
            } else {
                let idx = frames.len();
                frames.push(Frame {
                    name: root_name.clone(),
                    samples,
                    children: Vec::new(),
                });
                frame_map.insert(root_name.clone(), idx);
                root_indices.push(idx);
                idx
            };

            // Build the tree
            let mut current_idx = root_idx;
            for part in &stack_parts[1..] {
                let part_str = part.to_string();
                let full_path = format!("{};{}", frames[current_idx].name, part_str);

                let next_idx = if let Some(&idx) = frame_map.get(&full_path) {
                    frames[idx].samples += samples;
                    idx
                } else {
                    let idx = frames.len();
                    frames.push(Frame {
                        name: part_str,
                        samples,
                        children: Vec::new(),
                    });
                    frame_map.insert(full_path, idx);
                    idx
                };

                if !frames[current_idx].children.contains(&next_idx) {
                    frames[current_idx].children.push(next_idx);
                }

                current_idx = next_idx;
            }
        }

        Ok(FlameGraph {
            frames,
            root_indices,
            total_samples,
        })
    }

    pub fn get_frame_percentage(&self, frame_idx: usize) -> f64 {
        if self.total_samples == 0 {
            0.0
        } else {
            (self.frames[frame_idx].samples as f64 / self.total_samples as f64) * 100.0
        }
    }

    pub fn get_frame_percentage_of_parent(&self, frame_idx: usize, parent_idx: usize) -> f64 {
        if self.frames[parent_idx].samples == 0 {
            0.0
        } else {
            (self.frames[frame_idx].samples as f64 / self.frames[parent_idx].samples as f64) * 100.0
        }
    }
}
