}

fn draw_flamegraph(f: &mut Frame, area: Rect, app: &App) {
    let mut lines = Vec::new();

    // Get the frames to display
    let current_root = if app.zoom_stack.is_empty() {
        None
    } else {
        Some(app.zoom_stack[app.zoom_stack.len() - 1])
    };

    let display_frames = if let Some(root_idx) = current_root {
        // Show only children of the selected frame
        let mut frames = vec![root_idx];
        frames.extend(app.flamegraph.frames[root_idx].children.iter().cloned());
        frames
    } else {
        // Show all root frames
        let mut frames = app.flamegraph.root_indices.clone();
        // Add "all" as the first frame
        frames.insert(0, usize::MAX); // Special index for "all"
        frames
    };

    // Build the flamegraph display
    let mut row_items = Vec::new();
    for (i, &frame_idx) in display_frames.iter().enumerate() {
        let name = if frame_idx == usize::MAX {
            "all".to_string()
        } else {
            app.flamegraph.frames[frame_idx].name.clone()
        };

        let is_selected = if frame_idx == usize::MAX {
            app.selected_frame.is_none() && app.zoom_stack.is_empty()
        } else {
            app.selected_frame == Some(frame_idx)
        };

        let is_matched = if frame_idx == usize::MAX {
            false
        } else {
            app.matched_indices.contains(&frame_idx)
        };

        let style = if is_selected {
            Style::default()
                .bg(Color::Blue)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD)
        } else if is_matched {
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };

        row_items.push((name, style));
    }

    // Create spans for the flamegraph display
    let mut line_items = Vec::new();
    for (name, style) in row_items {
        line_items.push(Span::styled(name.clone() + "   ", style));
    }

    // Add a line with the frames
    if !line_items.is_empty() {
        lines.push(Line::from(line_items));
    }

    // Add empty lines
    for _ in 0..(area.height as usize).saturating_sub(1) {
        lines.push(Line::from(""));
    }

    let p = Paragraph::new(lines);
    f.render_widget(p, area);
}

fn draw_selected(f: &mut Frame, area: Rect, app: &App) {
    let block = Block::default()
        .title(" Selected ")
        .borders(Borders::TOP | Borders::BOTTOM);

    let mut lines = Vec::new();

    if app.in_search_mode {
        let search_line = Line::from(Span::raw(format!("Search ─────────────────────────────────────────────────────────────────────────────")));
        lines.push(search_line);
        lines.push(Line::from(Span::raw(app.search_pattern.clone())));
        lines.push(Line::from(Span::raw("".to_string())));
    } else if !app.matched_indices.is_empty() {
        if let Some(current_idx) = app.current_match_idx {
            let frame = &app.flamegraph.frames[current_idx];
            let percentage = app.flamegraph.get_frame_percentage(current_idx);
            let zoom_percentage = if let Some(root_idx) = app.zoom_stack.last() {
                app.flamegraph.get_frame_percentage_of_parent(current_idx, *root_idx)
            } else {
                percentage
            };

            let match_line = if app.zoom_stack.is_empty() {
                format!(
                    "Match ──────────────────────────────────────────────────────────────────────────────\n\
                    \"{}\" [{} samples, {:.2}% of all]",
                    app.search_pattern, frame.samples, percentage
                )
            } else {
                format!(
                    "Match ──────────────────────────────────────────────────────────────────────────────\n\
                    \"{}\" [{} samples, {:.2}% of zoomed]",
                    app.search_pattern, frame.samples, zoom_percentage
                )
            };

            for line_str in match_line.lines() {
                lines.push(Line::from(Span::raw(line_str.to_string())));
            }

            lines.push(Line::from(""));

            if let Some(selected) = app.selected_frame {
                let sel_frame = &app.flamegraph.frames[selected];
                let sel_percentage = app.flamegraph.get_frame_percentage(selected);
                let sel_zoom_percentage = if let Some(root_idx) = app.zoom_stack.last() {
                    app.flamegraph.get_frame_percentage_of_parent(selected, *root_idx)
                } else {
                    sel_percentage
                };

                let sel_line = if app.zoom_stack.is_empty() {
                    format!(
                        "{} [{} samples, {:.2}% of all]",
                        sel_frame.name, sel_frame.samples, sel_percentage
                    )
                } else {
                    format!(
                        "{} [{} samples, {:.2}% of all, {:.2}% of zoomed]",
                        sel_frame.name, sel_frame.samples, sel_percentage, sel_zoom_percentage
                    )
                };

                lines.push(Line::from(Span::raw(sel_line)));
            }
        }
    } else if let Some(selected) = app.selected_frame {
        let frame = &app.flamegraph.frames[selected];
        let percentage = app.flamegraph.get_frame_percentage(selected);
        let zoom_percentage = if let Some(root_idx) = app.zoom_stack.last() {
            app.flamegraph.get_frame_percentage_of_parent(selected, *root_idx)
        } else {
            percentage
        };

        let line_str = if app.zoom_stack.is_empty() {
            format!(
                "{} [{} samples, {:.2}% of all]",
                frame.name, frame.samples, percentage
            )
        } else {
            format!(
                "{} [{} samples, {:.2}% of all, {:.2}% of zoomed]",
                frame.name, frame.samples, percentage, zoom_percentage
            )
        };

        lines.push(Line::from(Span::raw(line_str)));
    } else {
        // Show "all" info
        let line_str = format!(
            "all [{} samples, 100.00% of all]",
            app.flamegraph.total_samples
        );
        lines.push(Line::from(Span::raw(line_str)));
    }

    while lines.len() < area.height as usize {
        lines.push(Line::from(""));
    }

    let p = Paragraph::new(lines).block(block);
    f.render_widget(p, area);
}

fn draw_footer(f: &mut Frame, area: Rect, _app: &App) {
    let footer = " [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like";
    let line = Line::from(Span::raw(footer));
    let p = Paragraph::new(line).style(Style::default().fg(Color::DarkGray));
    f.render_widget(p, area);
}
