use crate::flamegraph::FlameGraph;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Paragraph};
use ratatui::Frame;
use regex::Regex;
use std::collections::HashSet;

pub struct App {
    pub flamegraph: FlameGraph,
    pub filename: String,
    pub in_search_mode: bool,
    pub search_pattern: String,
    pub has_match: bool,
    pub selected_frame: Option<usize>,
    pub zoom_stack: Vec<usize>,
    pub matched_indices: HashSet<usize>,
    pub current_match_idx: Option<usize>,
}

impl App {
    pub fn new(flamegraph: FlameGraph) -> Self {
        App {
            flamegraph,
            filename: String::new(),
            in_search_mode: false,
            search_pattern: String::new(),
            has_match: false,
            selected_frame: None,
            zoom_stack: Vec::new(),
            matched_indices: HashSet::new(),
            current_match_idx: None,
        }
    }

    pub fn start_search(&mut self) {
        self.in_search_mode = true;
        self.search_pattern.clear();
    }

    pub fn cancel_search(&mut self) {
        self.in_search_mode = false;
        self.search_pattern.clear();
    }

    pub fn execute_search(&mut self) {
        self.in_search_mode = false;
        self.matched_indices.clear();
        self.current_match_idx = None;
        self.has_match = false;

        if let Ok(re) = Regex::new(&self.search_pattern) {
            for (idx, frame) in self.flamegraph.frames.iter().enumerate() {
                if re.is_match(&frame.name) {
                    self.matched_indices.insert(idx);
                    if self.current_match_idx.is_none() {
                        self.current_match_idx = Some(idx);
                        self.selected_frame = Some(idx);
                        self.has_match = true;
                    }
                }
            }
        }
    }

    pub fn search_like_selected(&mut self) {
        if let Some(selected) = self.selected_frame {
            self.search_pattern = format!("^{}$", regex::escape(&self.flamegraph.frames[selected].name));
            self.execute_search();
            self.in_search_mode = false;
        }
    }

    pub fn next_match(&mut self) {
        if let Some(current) = self.current_match_idx {
            let mut found = false;
            for idx in (current + 1)..self.flamegraph.frames.len() {
                if self.matched_indices.contains(&idx) {
                    self.current_match_idx = Some(idx);
                    self.selected_frame = Some(idx);
                    found = true;
                    break;
                }
            }
            if !found {
                // Wrap around to the beginning
                for idx in 0..current {
                    if self.matched_indices.contains(&idx) {
                        self.current_match_idx = Some(idx);
                        self.selected_frame = Some(idx);
                        break;
                    }
                }
            }
        }
    }

    pub fn prev_match(&mut self) {
        if let Some(current) = self.current_match_idx {
            let mut found = false;
            for idx in (0..current).rev() {
                if self.matched_indices.contains(&idx) {
                    self.current_match_idx = Some(idx);
                    self.selected_frame = Some(idx);
                    found = true;
                    break;
                }
            }
            if !found {
                // Wrap around to the end
                for idx in (current + 1..self.flamegraph.frames.len()).rev() {
                    if self.matched_indices.contains(&idx) {
                        self.current_match_idx = Some(idx);
                        self.selected_frame = Some(idx);
                        break;
                    }
                }
            }
        }
    }

    pub fn reset_view(&mut self) {
        self.zoom_stack.clear();
        self.selected_frame = None;
        self.matched_indices.clear();
        self.current_match_idx = None;
        self.has_match = false;
        self.search_pattern.clear();
    }

    pub fn zoom_in(&mut self) {
        if let Some(selected) = self.selected_frame {
            self.zoom_stack.push(selected);
        }
    }

    pub fn zoom_out(&mut self) {
        self.zoom_stack.pop();
        self.selected_frame = None;
    }

    pub fn move_cursor_left(&mut self) {
        // Move to parent in zoom stack
        if !self.zoom_stack.is_empty() {
            self.zoom_stack.pop();
        }
    }

    pub fn move_cursor_right(&mut self) {
        if let Some(selected) = self.selected_frame {
            if !self.flamegraph.frames[selected].children.is_empty() {
                self.zoom_stack.push(selected);
                self.selected_frame = Some(self.flamegraph.frames[selected].children[0]);
            }
        }
    }

    pub fn move_cursor_down(&mut self) {
        let current_root = if self.zoom_stack.is_empty() {
            None
        } else {
            Some(self.zoom_stack[self.zoom_stack.len() - 1])
        };

        let available_frames = if let Some(root_idx) = current_root {
            self.flamegraph.frames[root_idx].children.clone()
        } else {
            self.flamegraph.root_indices.clone()
        };

        if let Some(selected) = self.selected_frame {
            if let Some(pos) = available_frames.iter().position(|&idx| idx == selected) {
                if pos + 1 < available_frames.len() {
                    self.selected_frame = Some(available_frames[pos + 1]);
                }
            }
        } else if !available_frames.is_empty() {
            self.selected_frame = Some(available_frames[0]);
        }
    }

    pub fn move_cursor_up(&mut self) {
        let current_root = if self.zoom_stack.is_empty() {
            None
        } else {
            Some(self.zoom_stack[self.zoom_stack.len() - 1])
        };

        let available_frames = if let Some(root_idx) = current_root {
            self.flamegraph.frames[root_idx].children.clone()
        } else {
            self.flamegraph.root_indices.clone()
        };

        if let Some(selected) = self.selected_frame {
            if let Some(pos) = available_frames.iter().position(|&idx| idx == selected) {
                if pos > 0 {
                    self.selected_frame = Some(available_frames[pos - 1]);
                }
            }
        } else if !available_frames.is_empty() {
            self.selected_frame = Some(available_frames[available_frames.len() - 1]);
        }
    }

    pub fn scroll_down(&mut self) {
        // Placeholder for scroll functionality
    }

    pub fn scroll_up(&mut self) {
        // Placeholder for scroll functionality
    }

    pub fn scroll_to_bottom(&mut self) {
        // Placeholder for scroll functionality
    }

    pub fn scroll_to_top(&mut self) {
        // Placeholder for scroll functionality
    }
}

pub fn draw(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(0)
        .constraints([
            Constraint::Length(1),
            Constraint::Min(10),
            Constraint::Length(8),
            Constraint::Length(1),
        ])
        .split(f.area());

    // Header
    draw_header(f, chunks[0], app);

    // Main flamegraph area
    draw_flamegraph(f, chunks[1], app);

    // Selected info area
    draw_selected(f, chunks[2], app);

    // Footer
    draw_footer(f, chunks[3], app);
}

fn draw_header(f: &mut Frame, area: Rect, app: &App) {
    let header = if app.zoom_stack.is_empty() {
        format!(
            " [Flamegraph] | Top                 {}               flamelens v0.3.1",
            &app.filename
        )
    } else {
        format!(
            " [Flamegraph] | Zoom (level: {})                {}               flamelens v0.3.1",
            app.zoom_stack.len(),
            &app.filename
        )
    };

    let line = Line::from(Span::raw(header));
    let p = Paragraph::new(line).style(Style::default().bg(Color::DarkGray).fg(Color::White));
    f.render_widget(p, area);
}

fn draw_flamegraph(f: &mut Frame, area: Rect, app: &App) {
    let mut lines = Vec::new();

    // Get the frames to display
    let current_root = if app.zoom_stack.is_empty() {
        None
    } else {
        Some(app.zoom_stack[app.zoom_stack.len() - 1])
    };

    let display_frames = if let Some(root_idx) = current_root {
        // Show only children of the selected frame
        let mut frames = vec![root_idx];
        frames.extend(app.flamegraph.frames[root_idx].children.iter().cloned());
        frames
    } else {
        // Show all root frames
        let mut frames = app.flamegraph.root_indices.clone();
        // Add "all" as the first frame
        frames.insert(0, usize::MAX); // Special index for "all"
        frames
    };

    // Build the flamegraph display
    let mut row_items = Vec::new();
    for (i, &frame_idx) in display_frames.iter().enumerate() {
        let name = if frame_idx == usize::MAX {
            "all".to_string()
        } else {
            app.flamegraph.frames[frame_idx].name.clone()
        };

        let is_selected = if frame_idx == usize::MAX {
            app.selected_frame.is_none() && app.zoom_stack.is_empty()
        } else {
            app.selected_frame == Some(frame_idx)
        };

        let is_matched = if frame_idx == usize::MAX {
            false
        } else {
            app.matched_indices.contains(&frame_idx)
        };

        let style = if is_selected {
            Style::default()
                .bg(Color::Blue)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD)
        } else if is_matched {
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };

        row_items.push((name, style));
    }

    // Create spans for the flamegraph display
    let mut line_items = Vec::new();
    for (name, style) in row_items {
        line_items.push(Span::styled(name.clone() + "   ", style));
    }

    // Add a line with the frames
    if !line_items.is_empty() {
        lines.push(Line::from(line_items));
    }

    // Add empty lines
    for _ in 0..(area.height as usize).saturating_sub(1) {
        lines.push(Line::from(""));
    }

    let p = Paragraph::new(lines);
    f.render_widget(p, area);
}

