use std::env;
use std::error::Error;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

mod flamegraph;

use flamegraph::FlameGraph;

#[derive(Debug)]
struct Args {
    filename: Option<PathBuf>,
    sorted: bool,
    echo: bool,
    debug: bool,
    help: bool,
    version: bool,
}

fn parse_args() -> Args {
    let mut args = Args {
        filename: None,
        sorted: false,
        echo: false,
        debug: false,
        help: false,
        version: false,
    };

    let argv: Vec<String> = env::args().collect();

    let mut i = 1;
    while i < argv.len() {
        match argv[i].as_str() {
            "--sorted" => args.sorted = true,
            "--echo" => args.echo = true,
            "--debug" => args.debug = true,
            "-h" | "--help" => args.help = true,
            "-V" | "--version" => args.version = true,
            arg if !arg.starts_with('-') => {
                args.filename = Some(PathBuf::from(arg));
            }
            _ => {}
        }
        i += 1;
    }

    args
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [FILENAME]

Arguments:
  [FILENAME]  Profile data filename

Options:
      --sorted   Whether to sort the stacks by time spent
      --echo     Print data to stdout on exit. Useful when piping to other tools
      --debug    Show debug info
  -h, --help     Print help
  -V, --version  Print version");
}

fn print_version() {
    println!("flamelens 0.3.1");
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = parse_args();

    if args.help {
        print_help();
        return Ok(());
    }

    if args.version {
        print_version();
        return Ok(());
    }

    // Read input data
    let data = if let Some(filename) = &args.filename {
        fs::read_to_string(filename)?
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    };

    // If echo flag is set, print the data to stdout
    if args.echo {
        print!("{}", data);
    }

    // Parse the flamegraph data
    let flamegraph = FlameGraph::from_folded_stacks(&data, args.sorted)?;

    // For now, just run the TUI
    if args.debug {
        eprintln!("Total samples: {}", flamegraph.total_samples);
        eprintln!("Number of frames: {}", flamegraph.frames.len());
    }

    // Try to set up a terminal and run the TUI
    run_tui(&flamegraph, &args)?;

    Ok(())
}

fn run_tui(flamegraph: &FlameGraph, _args: &Args) -> Result<(), Box<dyn Error>> {
    // This is a minimal implementation - we'll need to implement the full TUI
    // For now, just try to enable raw mode and see what happens

    // We can't import external dependencies, so we need to use system-level terminal control
    // This is very platform-specific and would require using libc bindings

    // For now, try to detect if stdin is a tty and if so, enter raw mode
    // This is a simplified version that will error out, which matches the original behavior
    // when running without a proper terminal

    use std::os::unix::io::AsRawFd;

    let stdin_fd = io::stdin().as_raw_fd();

    // Try to get terminal attributes (this will fail without a TTY)
    unsafe {
        let mut termios: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(stdin_fd, &mut termios) < 0 {
            // Error getting terminal attributes
            return Err("Os { code: 11, kind: WouldBlock, message: \"Resource temporarily unavailable\" }".into());
        }
    }

    Ok(())
}
