use std::io::{self, Read, Write};

pub struct TerminalSize {
    pub width: u16,
    pub height: u16,
}

pub fn get_terminal_size() -> io::Result<TerminalSize> {
    // Try using ioctl to get terminal size
    // For now, return a default size
    Ok(TerminalSize {
        width: 80,
        height: 24,
    })
}

pub fn enable_raw_mode() -> io::Result<()> {
    // Try to enable raw mode using stty command
    // This is a Unix-specific implementation
    use std::process::Command;

    let status = Command::new("stty")
        .arg("raw")
        .arg("-echo")
        .status()?;

    if status.success() {
        Ok(())
    } else {
        Err(io::Error::new(
            io::ErrorKind::Other,
            "Failed to enable raw mode",
        ))
    }
}

pub fn disable_raw_mode() -> io::Result<()> {
    // Restore terminal mode using stty command
    use std::process::Command;

    let status = Command::new("stty")
        .arg("-raw")
        .arg("echo")
        .status()?;

    if status.success() {
        Ok(())
    } else {
        Err(io::Error::new(
            io::ErrorKind::Other,
            "Failed to disable raw mode",
        ))
    }
}

pub fn clear_screen() -> io::Result<()> {
    io::stdout().write_all(b"\x1B[2J")?;
    io::stdout().write_all(b"\x1B[H")?;
    io::stdout().flush()
}

pub fn hide_cursor() -> io::Result<()> {
    io::stdout().write_all(b"\x1B[?25l")?;
    io::stdout().flush()
}

pub fn show_cursor() -> io::Result<()> {
    io::stdout().write_all(b"\x1B[?25h")?;
    io::stdout().flush()
}

pub fn read_single_key() -> io::Result<u8> {
    let mut buf = [0u8; 1];
    io::stdin().read_exact(&mut buf)?;
    Ok(buf[0])
}
