use std::env;
use std::error::Error;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

mod flamegraph;
mod tui;
mod app;

use flamegraph::FlameGraph;
use app::App;

#[derive(Debug)]
struct Args {
    filename: Option<PathBuf>,
    sorted: bool,
    echo: bool,
    debug: bool,
    help: bool,
    version: bool,
}

fn parse_args() -> Args {
    let mut args = Args {
        filename: None,
        sorted: false,
        echo: false,
        debug: false,
        help: false,
        version: false,
    };

    let argv: Vec<String> = env::args().collect();

    let mut i = 1;
    while i < argv.len() {
        match argv[i].as_str() {
            "--sorted" => args.sorted = true,
            "--echo" => args.echo = true,
            "--debug" => args.debug = true,
            "-h" | "--help" => args.help = true,
            "-V" | "--version" => args.version = true,
            arg if !arg.starts_with('-') => {
                args.filename = Some(PathBuf::from(arg));
            }
            _ => {}
        }
        i += 1;
    }

    args
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [FILENAME]

Arguments:
  [FILENAME]  Profile data filename

Options:
      --sorted   Whether to sort the stacks by time spent
      --echo     Print data to stdout on exit. Useful when piping to other tools
      --debug    Show debug info
  -h, --help     Print help
  -V, --version  Print version");
}

fn print_version() {
    println!("flamelens 0.3.1");
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = parse_args();

    if args.help {
        print_help();
        return Ok(());
    }

    if args.version {
        print_version();
        return Ok(());
    }

    // Read input data
    let data = if let Some(filename) = &args.filename {
        fs::read_to_string(filename)?
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    };

    // If echo flag is set, print the data to stdout
    if args.echo {
        print!("{}", data);
    }

    // Parse the flamegraph data
    let flamegraph = FlameGraph::from_folded_stacks(&data, args.sorted)?;

    // Run the TUI
    if let Some(filename) = &args.filename {
        run_tui(&flamegraph, filename.to_string_lossy().to_string(), args.debug)?;
    } else {
        run_tui(&flamegraph, String::new(), args.debug)?;
    }

    Ok(())
}

fn run_tui(
    flamegraph: &FlameGraph,
    filename: String,
    debug: bool,
) -> Result<(), Box<dyn Error>> {
    // Create app
    let mut app = App::new(flamegraph, filename, debug);

    // Try to set up terminal
    match tui::enable_raw_mode() {
        Ok(()) => {
            // Terminal is set up, run the app
            tui::clear_screen()?;
            tui::hide_cursor()?;

            let result = app.run();

            // Restore terminal
            let _ = tui::show_cursor();
            let _ = tui::disable_raw_mode();

            result
        }
        Err(e) => {
            // Could not set up raw mode, return the error
            Err(Box::new(e))
        }
    }
}
