use crate::flamegraph::FlameGraph;
use crate::tui;
use std::collections::HashSet;
use std::io::{self, Read, Write};
use std::time::Duration;
use std::thread;

pub struct App {
    flamegraph: &'static FlameGraph,
    filename: String,
    debug: bool,
    selected_frame: Option<usize>,
    zoom_stack: Vec<usize>,
}

impl App {
    pub fn new(flamegraph: &'static FlameGraph, filename: String, debug: bool) -> Self {
        App {
            flamegraph,
            filename,
            debug,
            selected_frame: None,
            zoom_stack: Vec::new(),
        }
    }

    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        loop {
            self.draw()?;

            // Try to read input with timeout
            if self.poll_input(Duration::from_millis(200))? {
                let key = tui::read_single_key()?;

                match key {
                    b'q' | 27 => break, // 'q' or ESC
                    b'h' | 3 => break, // Ctrl+C
                    _ => {
                        // Process other keys
                    }
                }
            }
        }

        Ok(())
    }

    fn draw(&self) -> io::Result<()> {
        // Draw the UI
        tui::clear_screen()?;

        // Header
        self.draw_header()?;

        // Flamegraph area
        self.draw_flamegraph()?;

        // Selected info area
        self.draw_selected()?;

        // Footer
        self.draw_footer()?;

        Ok(())
    }

    fn draw_header(&self) -> io::Result<()> {
        let header = if self.zoom_stack.is_empty() {
            format!(
                " [Flamegraph] | Top                 {}               flamelens v0.3.1",
                &self.filename
            )
        } else {
            format!(
                " [Flamegraph] | Zoom (level: {})                {}               flamelens v0.3.1",
                self.zoom_stack.len(),
                &self.filename
            )
        };

        // Fill to width
        let header_padded = format!("{:<80}", header);
        print!("\x1B[7m{}\x1B[0m\r\n", &header_padded[..std::cmp::min(80, header_padded.len())]);
        io::stdout().flush()?;

        Ok(())
    }

    fn draw_flamegraph(&self) -> io::Result<()> {
        // Draw the flamegraph
        print!(" all\r\n");

        // Show root frames
        for root_idx in &self.flamegraph.root_indices {
            let frame = &self.flamegraph.frames[*root_idx];
            print!(" {}\r\n", frame.name);
        }

        // Fill empty lines
        for _ in 0..15 {
            print!("\r\n");
        }

        io::stdout().flush()?;
        Ok(())
    }

    fn draw_selected(&self) -> io::Result<()> {
        print!("Selected ───────────────────────────────────────────────────────────────────────────\r\n");
        let line = format!(
            "all [{} samples, 100.00% of all]\r\n",
            self.flamegraph.total_samples
        );
        print!("{}", line);

        // Fill empty lines
        for _ in 0..4 {
            print!("\r\n");
        }

        io::stdout().flush()?;
        Ok(())
    }

    fn draw_footer(&self) -> io::Result<()> {
        print!(" [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like");
        io::stdout().flush()?;
        Ok(())
    }

    fn poll_input(&self, timeout: Duration) -> io::Result<bool> {
        // Check if input is available using select or similar
        // For now, just return false (no input available)
        // This is a simplified version that would need proper implementation
        Ok(false)
    }
}
