}

fn parse_args() -> Args {
    let mut args = Args {
        filename: None,
        sorted: false,
        echo: false,
        debug: false,
        help: false,
        version: false,
    };

    let argv: Vec<String> = env::args().collect();

    let mut i = 1;
    while i < argv.len() {
        match argv[i].as_str() {
            "--sorted" => args.sorted = true,
            "--echo" => args.echo = true,
            "--debug" => args.debug = true,
            "-h" | "--help" => args.help = true,
            "-V" | "--version" => args.version = true,
            arg if !arg.starts_with('-') => {
                args.filename = Some(PathBuf::from(arg));
            }
            _ => {}
        }
        i += 1;
    }

    args
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [FILENAME]

Arguments:
  [FILENAME]  Profile data filename

Options:
      --sorted   Whether to sort the stacks by time spent
      --echo     Print data to stdout on exit. Useful when piping to other tools
      --debug    Show debug info
  -h, --help     Print help
  -V, --version  Print version");
}

fn print_version() {
    println!("flamelens 0.3.1");
}

fn main() {
