    if args.help {
        print_help();
        return;
    }

    if args.version {
        print_version();
        return;
    }

    // Read input data
    let data = match if let Some(filename) = &args.filename {
        fs::read_to_string(filename)
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer).map(|_| buffer)
    } {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    // If echo flag is set, print the data to stdout
    if args.echo {
        print!("{}", data);
    }

    // Parse the flamegraph data
    let flamegraph = match FlameGraph::from_folded_stacks(&data, args.sorted) {
        Ok(fg) => fg,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    // Run the TUI
    if let Some(filename) = &args.filename {
        if let Err(e) = run_tui(&flamegraph, filename.to_string_lossy().to_string(), args.debug) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else {
        if let Err(e) = run_tui(&flamegraph, String::new(), args.debug) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn run_tui(
    flamegraph: &FlameGraph,
    filename: String,
    debug: bool,
) -> Result<(), Box<dyn Error>> {
    // Create app
    let mut app = App::new(flamegraph, filename, debug);

    // Try to set up terminal
    match tui::enable_raw_mode() {
        Ok(()) => {
            // Terminal is set up, run the app
            tui::clear_screen()?;
            tui::hide_cursor()?;

            let result = app.run();

            // Restore terminal
            let _ = tui::show_cursor();
            let _ = tui::disable_raw_mode();

            result
        }
        Err(e) => {
            // Could not set up raw mode, return the error
            Err(Box::new(e))
        }
    }
}
