use crate::flamegraph::FlameGraph;
use crate::tui;
use std::io::{self, Read, Write};
use std::process::Command;
use std::thread;
use std::time::Duration;
use std::collections::HashMap;

pub struct App {
    flamegraph: FlameGraph,
    filename: String,
    debug: bool,
    selected_idx: usize, // Index in the current view
    zoom_stack: Vec<usize>, // Stack of zoomed frames
    search_pattern: String,
    in_search_mode: bool,
    matched_frames: Vec<usize>,
    current_match: usize,
}

impl App {
    pub fn new(flamegraph: &FlameGraph, filename: String, debug: bool) -> Self {
        App {
            flamegraph: flamegraph.clone(),
            filename,
            debug,
            selected_idx: 0,
            zoom_stack: Vec::new(),
            search_pattern: String::new(),
            in_search_mode: false,
            matched_frames: Vec::new(),
            current_match: 0,
        }
    }

    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        // Disable canonical mode but keep echo disabled
        let _ = Command::new("stty")
            .args(&["-icanon", "-echo", "time", "0"])
            .status();

        loop {
            self.draw()?;

            // Try to read input
            match self.read_key() {
                Ok(key) => {
                    if self.in_search_mode {
                        self.handle_search_key(key);
                    } else {
                        match key {
                            b'q' => break,
                            3 => break, // Ctrl+C
                            b'/' => self.start_search(),
                            b'h' | 68 => self.move_left(), // h or left arrow
                            b'l' | 67 => self.move_right(), // l or right arrow
                            b'j' | 66 => self.move_down(), // j or down arrow
                            b'k' | 65 => self.move_up(), // k or up arrow
                            b'f' => self.scroll_down(),
                            b'b' => self.scroll_up(),
                            b'G' => self.scroll_bottom(),
                            b'g' => self.scroll_top(),
                            b'\n' => self.zoom_in(),
                            27 => self.zoom_out(),
                            b'#' => self.search_like_selected(),
                            b'n' => self.next_match(),
                            b'N' => self.prev_match(),
                            b'r' => self.reset_view(),
                            _ => {}
                        }
                    }
                }
                Err(_) => {
                    // No input available, continue
                    thread::sleep(Duration::from_millis(100));
                }
            }
        }

        Ok(())
    }

    fn handle_search_key(&mut self, key: u8) {
        match key {
            b'\n' => {
                self.execute_search();
                self.in_search_mode = false;
            }
            8 | 127 => { // Backspace or Delete
                self.search_pattern.pop();
            }
            27 => { // ESC
                self.in_search_mode = false;
                self.search_pattern.clear();
            }
            32..=126 => { // Printable ASCII
                self.search_pattern.push(key as char);
            }
            _ => {}
        }
    }

    fn start_search(&mut self) {
        self.in_search_mode = true;
        self.search_pattern.clear();
    }

    fn execute_search(&mut self) {
        self.matched_frames.clear();
        self.current_match = 0;

        // Simple substring search
        for (idx, frame) in self.flamegraph.frames.iter().enumerate() {
            if frame.name.contains(&self.search_pattern) {
                self.matched_frames.push(idx);
            }
