            current_match: 0,
        }
    }

    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        // Disable canonical mode but keep echo disabled
        let _ = Command::new("stty")
            .args(&["-icanon", "-echo", "time", "0"])
            .status();

        loop {
            self.draw()?;

            // Try to read input
            match self.read_key() {
                Ok(key) => {
                    if self.in_search_mode {
                        self.handle_search_key(key);
                    } else {
                        match key {
                            b'q' => break,
                            3 => break, // Ctrl+C
                            b'/' => self.start_search(),
                            b'h' | 68 => self.move_left(), // h or left arrow
                            b'l' | 67 => self.move_right(), // l or right arrow
                            b'j' | 66 => self.move_down(), // j or down arrow
                            b'k' | 65 => self.move_up(), // k or up arrow
                            b'f' => self.scroll_down(),
                            b'b' => self.scroll_up(),
                            b'G' => self.scroll_bottom(),
                            b'g' => self.scroll_top(),
                            b'\n' => self.zoom_in(),
                            27 => self.zoom_out(),
                            b'#' => self.search_like_selected(),
                            b'n' => self.next_match(),
                            b'N' => self.prev_match(),
                            b'r' => self.reset_view(),
                            _ => {}
                        }
                    }
                }
                Err(_) => {
                    // No input available, continue
                    thread::sleep(Duration::from_millis(100));
                }
            }
        }

        Ok(())
    }

    fn handle_search_key(&mut self, key: u8) {
        match key {
            b'\n' => {
                self.execute_search();
                self.in_search_mode = false;
            }
            8 | 127 => { // Backspace or Delete
                self.search_pattern.pop();
            }
            27 => { // ESC
                self.in_search_mode = false;
                self.search_pattern.clear();
            }
            32..=126 => { // Printable ASCII
                self.search_pattern.push(key as char);
            }
            _ => {}
        }
    }

    fn start_search(&mut self) {
        self.in_search_mode = true;
        self.search_pattern.clear();
    }

    fn execute_search(&mut self) {
        self.matched_frames.clear();
        self.current_match = 0;

        // Simple substring search
        for (idx, frame) in self.flamegraph.frames.iter().enumerate() {
            if frame.name.contains(&self.search_pattern) {
                self.matched_frames.push(idx);
            }
        }
    }

    fn search_like_selected(&mut self) {
        let current_frames = self.get_current_frames();
        if let Some(&idx) = current_frames.get(self.selected_idx) {
            self.search_pattern = self.flamegraph.frames[idx].name.clone();
            self.execute_search();
        }
    }

    fn next_match(&mut self) {
        if !self.matched_frames.is_empty() {
            self.current_match = (self.current_match + 1) % self.matched_frames.len();
        }
    }

    fn prev_match(&mut self) {
        if !self.matched_frames.is_empty() {
            if self.current_match == 0 {
                self.current_match = self.matched_frames.len() - 1;
            } else {
                self.current_match -= 1;
            }
        }
    }

    fn reset_view(&mut self) {
        self.zoom_stack.clear();
        self.selected_idx = 0;
        self.search_pattern.clear();
        self.in_search_mode = false;
        self.matched_frames.clear();
        self.current_match = 0;
    }

    fn move_up(&mut self) {
        if self.selected_idx > 0 {
            self.selected_idx -= 1;
        }
    }

    fn move_down(&mut self) {
        let current_frames = self.get_current_frames();
        if self.selected_idx + 1 < current_frames.len() {
            self.selected_idx += 1;
        }
    }

    fn move_left(&mut self) {
        if !self.zoom_stack.is_empty() {
            self.zoom_stack.pop();
            self.selected_idx = 0;
        }
    }

    fn move_right(&mut self) {
        let current_frames = self.get_current_frames();
        if let Some(&idx) = current_frames.get(self.selected_idx) {
            if idx != usize::MAX && !self.flamegraph.frames[idx].children.is_empty() {
                self.zoom_stack.push(idx);
                self.selected_idx = 0;
            }
        }
    }

    fn zoom_in(&mut self) {
        let current_frames = self.get_current_frames();
        if let Some(&idx) = current_frames.get(self.selected_idx) {
            if idx != usize::MAX && !self.flamegraph.frames[idx].children.is_empty() {
                self.zoom_stack.push(idx);
                self.selected_idx = 0;
            }
        }
    }

    fn zoom_out(&mut self) {
        if !self.zoom_stack.is_empty() {
            self.zoom_stack.pop();
            self.selected_idx = 0;
        }
    }

