        // TODO: Implement scrolling
    }

    fn scroll_up(&mut self) {
        // TODO: Implement scrolling
    }

    fn scroll_bottom(&mut self) {
        // TODO: Implement scrolling
    }

    fn scroll_top(&mut self) {
        // TODO: Implement scrolling
    }

    fn get_current_frames(&self) -> Vec<usize> {
        if let Some(&parent_idx) = self.zoom_stack.last() {
            // Return children of the zoomed frame
            self.flamegraph.frames[parent_idx].children.clone()
        } else {
            // Return root frames
            self.flamegraph.root_indices.clone()
        }
    }

    fn draw(&self) -> io::Result<()> {
        // Draw the UI
        tui::clear_screen()?;

        // Header
        self.draw_header()?;

        // Flamegraph area
        self.draw_flamegraph()?;

        // Selected info area
        self.draw_selected()?;

        // Footer
        self.draw_footer()?;

        Ok(())
    }

    fn draw_header(&self) -> io::Result<()> {
        let header = if self.zoom_stack.is_empty() {
            format!(
                " [Flamegraph] | Top                 {}               flamelens v0.3.1",
                &self.filename
            )
        } else {
            format!(
                " [Flamegraph] | Zoom (level: {})                {}               flamelens v0.3.1",
                self.zoom_stack.len(),
                &self.filename
            )
        };

        // Fill to width
        let header_padded = format!("{:<80}", header);
        print!("\x1B[7m{}\x1B[0m\r\n", &header_padded[..std::cmp::min(80, header_padded.len())]);
        io::stdout().flush()?;

        Ok(())
    }

    fn draw_flamegraph(&self) -> io::Result<()> {
        let current_frames_with_all = if self.zoom_stack.is_empty() {
            // Show all roots plus "all" as first item
            let mut frames = vec![usize::MAX];
            frames.extend(self.flamegraph.root_indices.iter().cloned());
            frames
        } else {
            // Show children of the zoomed frame
            self.flamegraph.frames[*self.zoom_stack.last().unwrap()].children.clone()
        };

        // Draw the flamegraph display
        let mut items = Vec::new();
        for (i, &frame_idx) in current_frames_with_all.iter().enumerate() {
            let name = if frame_idx == usize::MAX {
                "all".to_string()
            } else {
                self.flamegraph.frames[frame_idx].name.clone()
            };

            let is_selected = i == self.selected_idx;
            let is_matched = !self.matched_frames.is_empty() && 
                (frame_idx == usize::MAX || self.matched_frames.contains(&frame_idx));

            if is_selected {
                items.push(format!("\x1B[7m{}\x1B[0m", name)); // Inverted
            } else if is_matched {
                items.push(format!("\x1B[33m{}\x1B[0m", name)); // Yellow
            } else {
                items.push(name);
            }
        }

        // Print items with spacing
        print!(" ");
        for (i, item) in items.iter().enumerate() {
            if i > 0 {
                print!("   ");
            }
            print!("{}", item);
        }
        println!("\r\n");

        // Fill empty lines
        for _ in 0..14 {
            println!("\r");
        }

        io::stdout().flush()?;
        Ok(())
    }

    fn draw_selected(&self) -> io::Result<()> {
        if self.in_search_mode {
            println!("Search ─────────────────────────────────────────────────────────────────────────────\r");
            println!("{}\r", self.search_pattern);
        } else {
            println!("Selected ───────────────────────────────────────────────────────────────────────────\r");

            let current_frames_with_all = if self.zoom_stack.is_empty() {
                let mut frames = vec![usize::MAX];
                frames.extend(self.flamegraph.root_indices.iter().cloned());
                frames
            } else {
                self.flamegraph.frames[*self.zoom_stack.last().unwrap()].children.clone()
            };

            if let Some(&frame_idx) = current_frames_with_all.get(self.selected_idx) {
                if frame_idx == usize::MAX {
                    println!("all [{} samples, 100.00% of all]\r", self.flamegraph.total_samples);
                } else {
                    let frame = &self.flamegraph.frames[frame_idx];
                    let percentage = (frame.samples as f64 / self.flamegraph.total_samples as f64) * 100.0;

                    if !self.matched_frames.is_empty() && self.matched_frames.contains(&frame_idx) {
                        println!("\"{}\" [{} samples, {:.2}% of all]\r", self.search_pattern, frame.samples, percentage);
                        println!("\r");
                        println!("{} [{} samples, {:.2}% of all]\r", frame.name, frame.samples, percentage);
                    } else {
                        println!("{} [{} samples, {:.2}% of all]\r", frame.name, frame.samples, percentage);
                    }
                }
            } else {
                // Show "all" info
                println!("all [{} samples, 100.00% of all]\r", self.flamegraph.total_samples);
            }
        }

        // Fill empty lines
        for _ in 0..3 {
            println!("\r");
        }

        io::stdout().flush()?;
        Ok(())
    }

    fn draw_footer(&self) -> io::Result<()> {
        print!(" [hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like");
        io::stdout().flush()?;
        Ok(())
    }

    fn read_key(&self) -> io::Result<u8> {
        let mut buf = [0u8; 1];
        let mut stdin = io::stdin();

        match stdin.read(&mut buf) {
            Ok(0) => Err(io::Error::new(io::ErrorKind::UnexpectedEof, "EOF")),
            Ok(_) => Ok(buf[0]),
            Err(e) => Err(e),
        }
    }
}
